#define SIN(x) (sin(x)*.5 +.5)


float n31(vec3 p) {return fract(sin(dot(p, vec3(42,54.32,542.343)))*423.);}
float n11(float h) {return fract(sin(h) * 43758.5453123);}

float noise(vec3 x) {
	vec3 p = floor(x);
	vec3 f = fract(x);
	f = f * f * (3.0 - 2.0 * f);

	float n = p.x + p.y * 157.0 + 113.0 * p.z;
	return mix(
			mix(mix(n11(n + 0.0), n11(n + 1.0), f.x),
					mix(n11(n + 157.0), n11(n + 158.0), f.x), f.y),
			mix(mix(n11(n + 113.0), n11(n + 114.0), f.x),
					mix(n11(n + 270.0), n11(n + 271.0), f.x), f.y), f.z);
}

float stars(vec2 p) {

    float N = 20.;
    vec2 id = floor(p*N)-.5;
    p = fract(p*N)-.5;

    float s = noise(vec3(id*20., 4));
    float v = float(noise(vec3(id*30., 6)) < .4);


    p.xy += vec2(noise(vec3(id*30., 1)), noise(vec3(id*20., 3)))*.3-.4;

    return 2.*(1.-pow(smoothstep(.0, .1*s, (length(p))), 3.))*v;
}

float fbm(vec3 p) {
	float f = 0.0;
	f = 0.5000 * noise(p*1.7); 
    p *= 2.01; f += 0.2500 * noise(p);
	p *= 2.02; f += .5*0.1250 * noise(p);
	return f;
}

float smax(float a, float b, float k) {
	float h = clamp(0.5 + 0.5 * (b - a) / k, 0.0, 1.0);
	return mix(a, b, h) + k * h * (1.0 - h);
}

vec2 path(float z) {
	return vec2(5.3 * sin(z * .4), 9. * cos(-3.14+z * .2));
}

float sdNoise(vec3 p) {
	p = p / 4.;
	return (fbm(p) - .3)*4.;
}

float map(vec3 p) {
	float d = sdNoise(p);   
	float d2 = length(p.xy-path(p.z/5.)-vec2(0, -5.)) - 1.5;
    d = smax(max(d, (p.y+2.-4.*SIN(2.*(p.z+p.x)))), -d2, 3.);    
	return d;
}

void mainImage(out vec4 fragColor, vec2 fragCoord) {
    float tt = 2. * iTime, res = .8, z;
    vec2 uv = (fragCoord - .5*iResolution.xy)/iResolution.y;
   // uv = uv.yx;

    vec3 R = iResolution,
         mask, side, n, p, q, border, col = vec3(0), 
         ro = vec3(path(tt), 5.*tt),
         fw = normalize(ro),
         rt = vec3(fw.z, 0, -fw.x),
         D = fw + mat2x3(rt, cross(fw, rt)) * uv;
    ro /= res; 

    ro.y -= 5.;
    p = floor(ro);
    side = (p - ro + .5) / D + .5 / abs(D);

    int i, far = 180;
    bool hit = false;

    while (q = p * res, i++ < far){
        if(map(q) < .0) {
            hit = true;
            col = .9*getPal(4, SIN(abs(q.x)*.35) + .5*SIN(q.y*.4));

            // blinking
            if(n31(p*.4) < .1) {
                col = mix(col, 1.1*getPal(1, 1.*SIN(q.x*2.+q.z)), SIN(p.y*1.+.5*p.z+2.*tt+n31(p*.06)));
            } 
            // letters
            if(n31(p*.3) > .4) {
                z = dot(side, mask);
                q = abs(fract(ro + z * D));
                int ascii =  int(10.+150.*n31(p*.04)+n31(p*.3+floor(mod((.2*SIN(.1*tt)+.5)*tt, 10.))));
                col -= .4*_char(iChannel0, (q.xy), ascii)*abs(n.z); // front
                col -= .4*_char(iChannel0, (q.zy), ascii)*abs(n.x); // side

            }

            break;
        }

        side += mask / abs(D);
        mask = step(side, side.yzx) * step(side, side.zxy);
        p += n = mask * sign(D);
    }

    z = dot(side, mask);
    q = abs(fract(ro + z * D) - .5);

    if(!hit) {
        col = mix(vec3(0.961,0.565,0.078)*1.3, vec3(0.282,0.196,0.702), uv.y*1.9+.45)*1.;
        float st = stars(uv);
        col = mix(col, .5*vec3(st), st);
    }

    // gamma
    col = pow(col*1.7, vec3(2.2));

    col *= (10. / z)* border(q, mask)*(1.-.8*length(q));
    fragColor.rgb = col;

}

#define COPY_COLOR(N, colorsK)  for(int i = 0; i < N; i++) { colors[i] = colorsK[i]; }

vec3 rgb2hsl(vec3 color) {
    float r = color.r;
    float g = color.g;
    float b = color.b;
    float max = max(max(r, g), b);
    float min = min(min(r, g), b);
    float h, s, l;
    l = (max + min) / 2.0;

    if (max == min) {
        h = s = 0.0; // achromatic
    } else {
        float d = max - min;
        s = l > 0.5 ? d / (2.0 - max - min) : d / (max + min);
        if (max == r) {
            h = (g - b) / d + (g < b ? 6.0 : 0.0);
        } else if (max == g) {
            h = (b - r) / d + 2.0;
        } else if (max == b) {
            h = (r - g) / d + 4.0;
        }
        h /= 6.0;
    }
    return vec3(h, s, l);
}


